flowDot:
digraph G {
  rankdir=TB; bgcolor="transparent"; nodesep=0.35; ranksep=0.45; newrank=true;
  node [fontname="Helvetica", fontsize=18, margin="0.2,0.1", style="rounded,filled", penwidth=2];
  edge [fontname="Helvetica", fontsize=16, penwidth=1.5, color="#6B7280"];
  ROLE [label="Role + context (who reads\nthe findings, why)", shape=box, style="rounded,filled", fillcolor="#EDE9FE", color="#7C3AED"];
  REPORT [label="⭐ Report: bugs, security,\ncomments that CONTRADICT code", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  SKIP [label="⭐ Skip: style, naming,\nlocal patterns", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  SEV [label="⭐ Severity levels, each with\na concrete code example", shape=box, style="rounded,filled", fillcolor="#FEF3C7", color="#D97706"];
  OFF [label="⭐ Noisy category? Switch it off\nwhile its criteria are fixed", shape=box, style="rounded,filled", fillcolor="#FEF3C7", color="#D97706"];
  OUT [label="Precise, consistent findings\ndevelopers trust", shape=box, style="rounded,filled", fillcolor="#EDE9FE", color="#7C3AED"];
  VAGUECOMMENT [label="✗ “check comments\nare accurate”", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  CONFIDENCE [label="✗ “be conservative /\nhigh-confidence only”", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  NOEXAMPLES [label="✗ severity levels\nwithout examples", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  NOISY [label="✗ noisy category\nleft on", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  ROLE -> REPORT; ROLE -> SKIP; { rank=same; REPORT; } { rank=same; SKIP; } REPORT -> SKIP [style=invis];
  REPORT -> SEV; SKIP -> SEV; SEV -> OFF; OFF -> OUT;
  { rank=same; VAGUECOMMENT; CONFIDENCE; } { rank=same; NOEXAMPLES; NOISY; } VAGUECOMMENT -> NOEXAMPLES [style=invis]; CONFIDENCE -> NOISY [style=invis];
  OUT -> VAGUECOMMENT [style=invis];
  KEY [shape=plain, label=<<TABLE BORDER="0" CELLBORDER="1" CELLSPACING="3" CELLPADDING="3"><TR><TD COLSPAN="2" BORDER="0" ALIGN="LEFT"><FONT POINT-SIZE="18"><B>Key</B></FONT></TD></TR><TR><TD BGCOLOR="#EDE9FE" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">the prompt</FONT></TD></TR><TR><TD BGCOLOR="#DBEAFE" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">explicit criteria</FONT></TD></TR><TR><TD BGCOLOR="#FEF3C7" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">severity & trust</FONT></TD></TR><TR><TD BGCOLOR="#FFFFFF" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">bug (a distractor)</FONT></TD></TR><TR><TD WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"><FONT POINT-SIZE="16">⭐</FONT></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">named by the exam guide (TS 4.1 p.16)</FONT></TD></TR></TABLE>>];
  VAGUECOMMENT -> KEY [style=invis];
}

decisionDot:
digraph D {
  rankdir=TB; bgcolor="transparent"; nodesep=0.35; ranksep=0.4;
  node [fontname="Helvetica", fontsize=18, margin="0.2,0.1", style="rounded,filled", fillcolor="#F3F4F6", color="#9CA3AF", penwidth=1.5];
  edge [fontname="Helvetica", fontsize=16, penwidth=1.5, color="#6B7280"];
  Q1 [shape=diamond, label="Too many false\npositives?"];
  Q2 [shape=diamond, label="Concentrated in\none category?"];
  OFF [shape=box, fillcolor="#FEF3C7", color="#D97706", label="Switch that category off;\nrewrite its criteria"];
  CRIT [shape=box, fillcolor="#DBEAFE", color="#0066CC", label="Replace vague words with\nReport / Skip categories"];
  Q3 [shape=diamond, label="Severities\ninconsistent?"];
  SEV [shape=box, fillcolor="#DBEAFE", color="#0066CC", label="Add a code example\nper severity level"];
  OK [shape=box, fillcolor="#D1FAE5", color="#059669", label="Keep measuring\ndismissal rates"];
  Q1 -> Q2 [label="yes"]; Q2 -> OFF [label="yes"]; Q2 -> CRIT [label="no"]; Q1 -> Q3 [label="no"];
  OFF -> Q3; CRIT -> Q3; Q3 -> SEV [label="yes"]; Q3 -> OK [label="no"]; SEV -> OK;
}
